1	import Fastify from "fastify";
2	import { PrismaClient } from "@prisma/client";
3	import jwt from "jsonwebtoken";
4	import bcrypt from "bcryptjs";
5	import dotenv from "dotenv";
6	
7	dotenv.config();
8	
9	const prisma = new PrismaClient();
10	const JWT_SECRET = process.env.JWT_SECRET || "ralph-secret";
11	
12	// Fastify 타입 확장
13	declare module "fastify" {
14	  interface FastifyRequest {
15	    userId?: number;
16	  }
17	}
18	
19	// ──────────────────────────────────────────────────────────────
20	// 유틸리티 함수들
21	// ──────────────────────────────────────────────────────────────
22	
23	// 사용자 응답 포맷터
24	function formatUserResponse(user: any, token: string) {
25	  return {
26	    user: {
27	      username: user.username,
28	      email: user.email,
29	      bio: user.bio,
30	      image: user.image,
31	      token,
32	    },
33	  };
34	}
35	
36	// 아티클 응답 포맷터
37	function formatArticleResponse(article: any, favorited: boolean, favoritesCount: number) {
38	  const tags: string[] = (article.tags || []).map((t: any) => t.tag);
39	  const { tags: _tags, ...rest } = article;
40	  return {
41	    ...rest,
42	    tagList: tags,
43	    favorited,
44	    favoritesCount,
45	  };
46	}
47	
48	// 인증 미들웨어
49	async function authMiddleware(request: any, reply: any) {
50	  const authHeader = request.headers.authorization;
51	  if (!authHeader) {
52	    reply.code(401).send({ errors: { token: ["is missing"] } });
53	    return;
54	  }
55	  const parts = authHeader.split(" ");
56	  if (parts[0] !== "Token") {
57	    reply.code(401).send({ errors: { token: ["is invalid"] } });
58	    return;
59	  }
60	  try {
61	    const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
62	    request.userId = decoded.id;
63	  } catch {
64	    reply.code(401).send({ errors: { token: ["is invalid"] } });
65	    return;
66	  }
67	}
68	
69	// 슬러그 생성 헬퍼
70	function generateSlug(title: string): string {
71	  return title.toLowerCase().replace(/\s+/g, "-");
72	}
73	
74	// ──────────────────────────────────────────────────────────────
75	// Fastify 앱 초기화
76	// ──────────────────────────────────────────────────────────────
77	
78	const app = Fastify({
79	  logger: true,
80	});
81	
82	// CORS 수동 설정
83	app.addHook("onRequest", async (request: any, reply: any) => {
84	  reply.header("Access-Control-Allow-Origin", "*");
85	  reply.header("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");
86	  reply.header("Access-Control-Allow-Headers", "Content-Type, Authorization");
87	  if (request.method === "OPTIONS") {
88	    reply.code(204).send();
89	    return;
90	  }
91	});
