93	// ──────────────────────────────────────────────────────────────
94	// 사용자 API
95	// ──────────────────────────────────────────────────────────────
96	
97	// 회원가입
98	app.post("/api/users", async (request: any, reply: any) => {
99	  const { username, email, password } = request.body?.user || {};
100	  if (!username || !email || !password) {
101	    const errs: Record<string, string[]> = {};
102	    if (!username) errs.username = ["can't be blank"];
103	    if (!email) errs.email = ["can't be blank"];
104	    if (!password) errs.password = ["can't be blank"];
105	    reply.code(422).send({ errors: errs });
106	    return;
107	  }
108	  const existing = await prisma.user.findFirst({
109	    where: { OR: [{ username }, { email }] },
110	  });
111	  if (existing) {
112	    const err: Record<string, string[]> = {};
113	    if (existing.username === username) err.username = ["has already been taken"];
114	    if (existing.email === email) err.email = ["has already been taken"];
115	    reply.code(409).send({ errors: err });
116	    return;
117	  }
118	  const hashedPassword = await bcrypt.hash(password, 10);
119	  const user = await prisma.user.create({
120	    data: { username, email, password: hashedPassword },
121	  });
122	  const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
123	  reply.code(201).send(formatUserResponse(user, token));
124	  return;
125	});
126	
127	// 로그인
128	app.post("/api/users/login", async (request: any, reply: any) => {
129	  const { email, password } = request.body?.user || {};
130	  const user = await prisma.user.findUnique({ where: { email: email as string } });
131	  if (!user) {
132	    reply.code(422).send({ errors: { email: ["can't be blank"] } });
133	    return;
134	  }
135	  const match = await bcrypt.compare(password, user.password);
136	  if (!match) {
137	    reply.code(422).send({ errors: { password: ["can't be blank"] } });
138	    return;
139	  }
140	  const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
141	  reply.code(200).send(formatUserResponse(user, token));
142	  return;
143	});
