145	// 현재 사용자 조회
146	app.get("/api/user", { preHandler: authMiddleware }, async (request: any, reply: any) => {
147	  const user = await prisma.user.findUniqueOrThrow({ where: { id: request.userId } });
148	  const token = request.headers.authorization.split(" ")[1];
149	  return formatUserResponse(user, token);
150	});
