152	// 사용자 정보 수정
153	app.put("/api/user", { preHandler: authMiddleware }, async (request: any, reply: any) => {
154	  const body = request.body?.user || {};
155	  const updates: any = {};
156	  if (body.username !== undefined) {
157	    if (body.username === "" || body.username === null) {
158	      reply.code(422).send({ errors: { username: ["can't be blank"] } });
159	      return;
160	    }
161	    updates.username = body.username;
162	  }
163	  if (body.email !== undefined) {
164	    if (body.email === "" || body.email === null) {
165	      reply.code(422).send({ errors: { email: ["can't be blank"] } });
166	      return;
167	    }
168	    updates.email = body.email;
169	  }
170	  if (body.bio !== undefined) updates.bio = body.bio === "" ? null : body.bio;
171	  if (body.image !== undefined) updates.image = body.image === "" ? null : body.image;
172	  if (body.password !== undefined) {
173	    if (body.password === "" || body.password === null || body.password.length < 8) {
174	      reply.code(422).send({ errors: { password: ["is too short (minimum is 8 characters)"] } });
175	      return;
176	    }
177	    updates.password = await bcrypt.hash(body.password, 10);
178	  }
179	
180	  // 고유성 검증
181	  if (updates.username || updates.email) {
182	    const existing = await prisma.user.findFirst({
183	      where: {
184	        id: { not: request.userId },
185	        OR: [
186	          updates.username !== undefined ? { username: updates.username } : undefined,
187	          updates.email !== undefined ? { email: updates.email } : undefined,
188	        ].filter((e: any) => e !== undefined),
189	      },
190	    });
191	    if (existing) {
192	      const err: Record<string, string[]> = {};
193	      if (updates.username && existing.username === updates.username) err.username = ["has already been taken"];
194	      if (updates.email && existing.email === updates.email) err.email = ["has already been taken"];
195	      reply.code(422).send({ errors: err });
196	      return;
197	    }
198	  }
199	
200	  const user = await prisma.user.update({
201	    where: { id: request.userId },
202	    data: updates,
203	  });
204	  const token = request.headers.authorization.split(" ")[1];
205	  return formatUserResponse(user, token);
206	});
