212	// 프로필 조회
213	app.get("/api/profiles/:username", async (request: any, reply: any) => {
214	  const username = request.params.username as string;
215	  const profile = await prisma.user.findUnique({
216	    where: { username },
217	    select: { id: true, username: true, bio: true, image: true },
218	  });
219	  if (!profile) {
220	    reply.code(404).send({ errors: { profile: ["can't be found"] } });
221	    return;
222	  }
223	
224	  // 팔로우 상태 확인 (인증된 경우)
225	  let following = false;
226	  const authHeader = request.headers.authorization;
227	  if (authHeader) {
228	    const parts = authHeader.split(" ");
229	    if (parts[0] === "Token") {
230	      try {
231	        const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
232	        const follow = await prisma.follow.findUnique({
233	          where: { followerId_followingId: { followerId: decoded.id, followingId: profile.id } },
234	        });
235	        following = !!follow;
236	      } catch {
237	        following = false;
238	      }
239	    }
240	  }
241	
242	  return { profile: { ...profile, following } };
243	});
