246	app.post("/api/profiles/:username/follow", { preHandler: authMiddleware }, async (request: any, reply: any) => {
247	  const username = request.params.username as string;
248	  const target = await prisma.user.findUnique({
249	    where: { username },
250	    select: { id: true },
251	  });
252	  if (!target) {
253	    reply.code(404).send({ errors: { profile: ["can't be found"] } });
254	    return;
255	  }
256	  if (target.id === request.userId) {
257	    reply.code(422).send({ errors: { profile: ["can't follow yourself"] } });
258	    return;
259	  }
260	  await prisma.follow.upsert({
261	    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
262	    create: { followerId: request.userId, followingId: target.id },
263	    update: {},
264	  });
265	  const profile = await prisma.user.findUnique({
266	    where: { username },
267	    select: { id: true, username: true, bio: true, image: true },
268	  });
269	  const isFollowing = await prisma.follow.findUnique({
270	    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
271	  });
272	  return { profile: { ...profile, following: !!isFollowing } };
273	});
