276	app.delete("/api/profiles/:username/follow", { preHandler: authMiddleware }, async (request: any, reply: any) => {
277	  const username = request.params.username as string;
278	  const target = await prisma.user.findUnique({
279	    where: { username },
280	    select: { id: true },
281	  });
282	  if (!target) {
