304	app.post("/api/articles", { preHandler: authMiddleware }, async (request: any, reply: any) => {
305	  const { title, description, body, tagList = [] } = request.body?.article || {};
306	  if (!title || !description || !body) {
307	    const errs: Record<string, string[]> = {};
308	    if (!title) errs.title = ["can't be blank"];
309	    if (!description) errs.description = ["can't be blank"];
310	    if (!body) errs.body = ["can't be blank"];
311	    reply.code(422).send({ errors: errs });
312	    return;
313	  }
314	  const slug = generateSlug(title);
315	  const article = await prisma.article.create({
316	    data: {
317	      slug,
318	      title,
319	      description,
320	      body,
321	      author: { connect: { id: request.userId } },
322	      tags: {
323	        create: tagList.map((t: string) => ({ tag: t.toLowerCase() })),
324	      },
325	    },
326	    include: {
327	      author: { select: { username: true, bio: true, image: true } },
328	      tags: true,
329	      favorites: true,
330	    },
331	  });
332	  reply.code(201).send({
333	    article: formatArticleResponse(article, false, article.favorites.length),
334	  });
335	  return;
336	});
