338	// 아티클 목록 조회
339	app.get("/api/articles", async (request: any, reply: any) => {
340	  const { author, tag, favorited, limit = "20", offset = "0" } = request.query || {};
341	  const lim = parseInt(limit as string, 10);
342	  const off = parseInt(offset as string, 10);
343	
344	  const where: any = {};
345	  if (author) {
346	    const user = await prisma.user.findUnique({ where: { username: author as string }, select: { id: true } });
347	    if (!user) {
348	      return { articles: [], articlesCount: 0 };
349	    }
350	    where.authorId = user.id;
351	  }
352	  if (tag) {
353	    where.tags = { some: { tag: (tag as string).toLowerCase() } };
354	  }
355	
356	  if (favorited) {
357	    const user = await prisma.user.findUnique({
358	      where: { username: favorited as string },
359	      select: { id: true },
360	    });
361	    if (!user) {
362	      return { articles: [], articlesCount: 0 };
363	    }
364	    const favorites = await prisma.favorite.findMany({
365	      where: { userId: user.id },
366	      select: { articleId: true },
367	    });
368	    const articleIds = favorites.map((f: any) => f.articleId);
369	    if (articleIds.length === 0) {
370	      return { articles: [], articlesCount: 0 };
371	    }
372	    const articles = await prisma.article.findMany({
373	      where: { id: { in: articleIds } },
374	      take: lim,
375	      skip: off,
376	      orderBy: { createdAt: "desc" },
377	      include: { author: { select: { username: true, bio: true, image: true } }, tags: true },
378	    });
379	    return {
380	      articles: articles.map((a: any) => formatArticleResponse(a, false, a.favorites.length)),
381	      articlesCount: articles.length,
382	    };
383	  }
384	
385	  const articles = await prisma.article.findMany({
386	    where,
387	    take: lim,
388	    skip: off,
389	    orderBy: { createdAt: "desc" },
390	    include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
391	  });
392	  const articlesCount = await prisma.article.count({ where });
393	  return {
394	    articles: articles.map((a: any) => formatArticleResponse(a, false, a.favorites.length)),
395	    articlesCount,
396	  };
397	});
