414	app.put("/api/articles/:slug", { preHandler: authMiddleware }, async (request: any, reply: any) => {
415	  const slug = request.params.slug as string;
416	  const article = await prisma.article.findUnique({ where: { slug } });
417	  if (!article) {
418	    reply.code(404).send({ errors: { article: ["not found"] } });
419	    return;
420	  }
421	  if (article.authorId !== request.userId) {
422	    reply.code(403).send({ errors: { article: ["forbidden"] } });
423	    return;
424	  }
425	
426	  const body = request.body?.article || {};
427	  const updates: any = {};
428	  if (body.title !== undefined) updates.title = body.title;
429	  if (body.description !== undefined) updates.description = body.description;
430	  if (body.body !== undefined) updates.body = body.body;
431	
432	  // 태그 업데이트
433	  if (body.tagList !== undefined) {
434	    if (body.tagList === null) {
435	      reply.code(422).send({ errors: { article: ["tagList는 null일 수 없습니다"] } });
436	      return;
437	    }
438	    if (Array.isArray(body.tagList)) {
439	      await prisma.articleTag.deleteMany({ where: { articleId: article.id } });
440	      if (body.tagList.length > 0) {
441	        await prisma.articleTag.createMany({
442	          data: body.tagList.map((t: string) => ({ articleId: article.id, tag: t.toLowerCase() })),
443	        });
444	      }
445	    }
446	  }
447	
448	  // 슬러그 업데이트
449	  if (updates.title) {
450	    updates.slug = generateSlug(updates.title);
451	  }
452	
453	  const updated = await prisma.article.update({
454	    where: { id: article.id },
455	    data: updates,
456	    include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
457	  });
458	  return { article: formatArticleResponse(updated, false, updated.favorites.length) };
459	});
