// 사용자 정보 수정
app.put("/api/user", { preHandler: authMiddleware }, async (request: any, reply: any) => {
  const body = request.body?.user || {};
  const updates: any = {};
  if (body.username !== undefined) {
    if (body.username === "" || body.username === null) {
      reply.code(422).send({ errors: { username: ["can't be blank"] } });
      return;
    }
    updates.username = body.username;
  }
  if (body.email !== undefined) {
    if (body.email === "" || body.email === null) {
      reply.code(422).send({ errors: { email: ["can't be blank"] } });
      return;
    }
    updates.email = body.email;
  }
  if (body.bio !== undefined) updates.bio = body.bio === "" ? null : body.bio;
  if (body.image !== undefined) updates.image = body.image === "" ? null : body.image;
  if (body.password !== undefined) {
    if (body.password === "" || body.password === null || body.password.length < 8) {
      reply.code(422).send({ errors: { password: ["is too short (minimum is 8 characters)"] } });
      return;
    }
    updates.password = await bcrypt.hash(body.password, 10);
  }

  // 고유성 검증
  if (updates.username || updates.email) {
    const existing = await prisma.user.findFirst({
      where: {
        id: { not: request.userId },
        OR: [
          updates.username !== undefined ? { username: updates.username } : undefined,
          updates.email !== undefined ? { email: updates.email } : undefined,
        ].filter((e: any) => e !== undefined),
      },
    });
    if (existing) {
      const err: Record<string, string[]> = {};
      if (updates.username && existing.username === updates.username) err.username = ["has already been taken"];
      if (updates.email && existing.email === updates.email) err.email = ["has already been taken"];
      reply.code(422).send({ errors: err });
      return;
    }
  }

  const user = await prisma.user.update({
    where: { id: request.userId },
    data: updates,
  });
  const token = request.headers.authorization.split(" ")[1];
  return formatUserResponse(user, token);
});

// ──────────────────────────────────────────────────────────────
// 프로필 API
// ──────────────────────────────────────────────────────────────

